import ast, hashlib, json, os, shutil, subprocess as sp, sys, textwrap, time
from pathlib import Path
from datetime import datetime, timezone

HERE = Path(__file__).resolve().parent
WORK = HERE.parent
REPO = Path('/home/ativaro/Documents/tide')
OUT = REPO/'experimente/25_blinde_quellreparatur'
TIDE = str(REPO/'tide')
F = json.loads((OUT/'versuchsplan.json').read_text())
def write(path, value):
    path.write_text(json.dumps(value, ensure_ascii=False, indent=2)+'\n')
def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()
def run(cmd, cwd, **kw):
    return sp.run(cmd, cwd=cwd, text=True, capture_output=True, **kw)
def public(path, folder):
    p = run([path/'verify'], folder)
    if p.returncode not in (0,1) or not p.stdout.strip(): raise ValueError(p.stderr or p.stdout)
    data = json.loads(p.stdout)
    assert bool(data['failed']) == bool(p.returncode)
    return data
def execute(lang, folder, cases):
    batches = json.dumps([c['input'] for c in cases], separators=(',',':'))
    if lang=='tide': p = run([TIDE,'run','summary.tide','--inputs','{"batches":'+batches+'}'],folder)
    else: p = run([sys.executable,'-B','-c','from summary import main; import json,sys; print(json.dumps(main(json.load(sys.stdin))))'],folder,input=batches)
    p.check_returncode()
    return json.loads(p.stdout)
def source(folder, bug, lang, faults):
    d = F['families'][bug]
    folder.mkdir(parents=True,exist_ok=True)
    for name, text in d['canonical'].items():
        prefix, fname = name.split('/')
        if prefix != lang: continue
        for i,(file,old,new) in enumerate(d['mutations'][lang]):
            if i in faults and fname==file:
                assert text.count(old)==1
                text = text.replace(old,new)
        (folder/fname).write_text(text)
def inputs(bug):
    d=F['families'][bug]
    return d['public'],d['hidden']
def preflight():
    history={}
    for bug in F['families']:
        pub,hid = inputs(bug)
        for suite,cases in [('public',pub),('hidden',hid)]:
            gate=WORK/suite/bug
            gate.mkdir(exist_ok=True,parents=True)
            write(gate/'cases.json',cases)
            shutil.copy2(HERE/'verify',gate/'verify')
        states={}
        for label, faults in [('red',(0,1)),('only_first_fault',(0,)),('only_second_fault',(1,)),('green',())]:
            values=[]
            for lang in ('tide','python'):
                p=WORK/'calibration'/bug/label/lang
                source(p,bug,lang,faults)
                values.append(execute(lang,p,pub+hid))
            assert values[0]==values[1] and len(values[0])==len(pub+hid)
            counts=[]
            for start,cases in [(0,pub),(len(pub),hid)]:
                count=sum(y['expect']==values[0][i+start] for i,y in enumerate(cases))
                assert (count==len(cases))==(label=='green'), (bug,label,start,count,len(cases))
                counts.append(count)
            states[label]=counts
        history[bug]={'n':[len(pub),len(hid)],'stages':states}
    return history
def usage(events):
    usage=[v['usage'] for v in events if v['type']=='turn.completed']
    if not usage: raise RuntimeError('no provider usage')
    return {k:sum(u.get(k,0) for u in usage) for k in usage[0]}
def python_edit(folder, edits):
    functions={}
    files={}
    for path in sorted(folder.glob('*.py')):
        source=path.read_text(); lines=source.splitlines(keepends=True); files[path]=lines
        for fn in ast.parse(source).body:
            if isinstance(fn,ast.FunctionDef):
                assert fn.name not in functions
                functions[fn.name]=(path,fn.body[0].lineno-1,fn.end_lineno)
    pending={}
    for e in edits:
        path,lo,hi=functions[e['name']]
        old=''.join(files[path][lo:hi]).rstrip('\n')
        before,after=e['before'],e['after']
        if before:
            pos=old.find(before)
            if pos<0 or old.find(before,pos+1)>=0: raise ValueError('absent or ambiguous fragment')
            body=old[:pos]+after+old[pos+len(before):]
        else: body=textwrap.indent(textwrap.dedent(after).strip('\n'),'    ')
        if not body.strip(): raise ValueError('empty candidate body')
        pending.setdefault(path,[]).append((lo,hi,body+'\n'))
    candidates={}
    for path,changes in pending.items():
        lines=files[path][:]
        for lo,hi,body in sorted(changes,reverse=True): lines[lo:hi]=[body]
        text=''.join(lines); compile(text,str(path),'exec'); candidates[path]=text
    for path,text in candidates.items(): path.write_text(text)
def apply(folder,arm,cache,answer):
    edits=answer['edits']
    if not edits or len({e['name'] for e in edits})!=len(edits): raise ValueError('empty edits or duplicate target')
    if arm=='P': return python_edit(folder,edits)
    forms=json.loads((cache/'forms').read_text())
    files=json.loads((cache/'input').read_text())['units']
    if any((folder/f['file']).read_text()!=f['source'] for f in files): raise ValueError('stale view')
    tool,fn = ('function_body','candidate_files') if arm=='B' else ('function_fragment','fragment_files')
    data=json.dumps(dict(forms=forms,files=files,edits=edits))
    p=run([TIDE,'run',str(REPO/'workbench'/(tool+'.tide')),'--call',fn,'--inputs',data],folder)
    if p.returncode: raise ValueError((p.stderr or p.stdout)[:1500])
    for f in json.loads(p.stdout): (folder/f['file']).write_text(f['source'])
COMMON="Repair the regression in production code, preserving the public interface. The complete reachable sources are below. All work is confined to this directory. You may inspect its sources and run ./verify. The runner applies your edits together. Give one edit per changed function."
FRAG="Use name, before, after. Replace a unique exact substring of the displayed function body. An empty before replaces the entire body."
GUIDES={'B':"Return name and complete single-line TIDE body.",'F':FRAG+" TIDE result bodies must be single-line expressions.",'P':FRAG+" For a whole Python body omit the def line."}
TIDE_GUIDE="The TIDE compiler grouped each body: (if test yes no), (fold items seed accumulator row item step)."
def trial(bug,rep,arm,basehash):
    lang = 'python' if arm=='P' else 'tide'
    folder = WORK/'project'
    shutil.rmtree(folder); folder.mkdir()
    source(folder,bug,lang,(0,1))
    gate=WORK/'public'/bug
    (folder/'verify').symlink_to(gate/'verify')
    cache=WORK/'runs'/f'{bug}-{rep}-{arm}'; cache.mkdir()
    utc=datetime.now(timezone.utc).isoformat()
    start=time.monotonic()
    before=public(gate,folder)
    assert before['failed']
    obs=json.dumps(before,separators=(',',':'),ensure_ascii=False)
    if arm=='P': files=[dict(file=f.name,source=f.read_text()) for f in sorted(folder.glob('*.py'))]
    else:
        p=run([HERE/'view',cache,'summary.tide','main',obs,'source_repair' if arm=='S' else 'fragment_view'],folder); p.check_returncode()
        files=json.loads((cache/'grouped').read_text())['files']
    packet='\n\n'.join(f"--- {f['file']} ---\n{f['source']}" for f in sorted(files,key=lambda f:f['file']))
    if arm=='P': guide="Inventory, reachable sources and ./verify are from this checked snapshot. Use them for your first proposal. Inspect only for missing facts. Give name, before, after. Replace one unique substring of the displayed body, or use empty before for the whole body. Python: omit the def line for a whole body."
    else: guide=json.loads((cache/'grouped').read_text())['instruction']
    prompt='\n\n'.join([F['families'][bug]['contract'], COMMON+' '+guide,obs,packet])
    attempts=[]
    feedback=''
    ready=time.monotonic()
    for attempt in range(1,4):
        full=prompt+feedback
        proc=run(['timeout','180','codex','exec','--ignore-user-config','--disable','memories','--disable','hooks','--disable','plugins','--enable','skip_host_skill_discovery','--ephemeral','--skip-git-repo-check','-s','read-only','-m',F['model'],'-c','model_reasoning_effort="'+F['effort']+'"','-c','service_tier="'+F['tier']+'"','-C',folder,'--json','--output-schema',HERE/('body' if arm=='B' else 'fragment'),'--output-last-message',cache/f'answer_{attempt}','-'],folder,input=full)
        if proc.returncode:
            (cache/'cli_failure').write_text((proc.stderr+'\n'+proc.stdout)[-2500:])
            raise RuntimeError('CLI failure; see '+str(cache/'cli_failure'))
        events=[json.loads(x) for x in proc.stdout.splitlines() if x.strip()]
        answer=json.loads((cache/f'answer_{attempt}').read_text())
        candidate=cache/f'candidate_{attempt}'
        source(candidate,bug,lang,(0,1))
        try:
            apply(candidate,arm,cache,answer); result=public(gate,candidate)
        except (ValueError,KeyError,SyntaxError,AssertionError) as ex:
            result={'error':str(ex)[:1600]}
        end=time.monotonic()
        ok=result.get('failed')==0
        attempts.append(dict(prompt=full,answer=answer,usage=usage(events),notices=[v['item'].get('message','')[:350] for v in events if v['type']=='item.completed' and v['item']['type']=='error'],session=[v['thread_id'] for v in events if v['type']=='thread.started'],tools=[v['item'].get('command',v['item']['type']) for v in events if v['type']=='item.completed' and v['item']['type'] not in ('agent_message','reasoning')],result=result))
        if ok: break
        feedback='\n\nApply the complete corrected proposal to the original sources. Previous response and public result:\n'+json.dumps([answer,result])
    replay={}
    if ok:
        fresh=cache/'replay'; source(fresh,bug,lang,(0,1)); apply(fresh,arm,cache,answer)
        replay={suite:public(WORK/suite/bug,fresh) for suite in ('public','hidden')}
    row=dict(bug=bug,rep=rep,arm=arm,utc=utc,seconds=end-start,prep=ready-start,passed=ok,replay=replay,attempts=attempts,plan_sha256=basehash)
    write(cache/'trial.json',row)
    print(bug,rep,arm,round(row['seconds'],2),ok,replay.get('hidden',{}).get('failed'),flush=True)
    return row

def main():
    schemas={}
    for n,cols in [('body',['name','body']),('fragment',['name','before','after'])]:
        obj={'type':'object','properties':{k:{'type':'string'} for k in cols},'required':cols,'additionalProperties':False}
        schema={'type':'object','properties':{'edits':{'type':'array','items':obj}},'required':['edits'],'additionalProperties':False}
        write(HERE/n,schema)
    pre=preflight()
    print(pre,flush=True)
    write(WORK/'pre.json',pre)
    if 'pre' in sys.argv: return
    basehash=sha(OUT/'versuchsplan.json')
    rows=[]
    for bug,rep,order in F['seq']:
        for arm in order:
            assert sha(OUT/'versuchsplan.json')==basehash
            rows.append(trial(bug,rep,arm,basehash))
    write(OUT/'messung.json',dict(source_view_sha256=sha(REPO/'workbench/source_repair.tide'),view_sha256=sha(REPO/'workbench/grouped_view.tide'),plan=basehash,preflight=pre,tool_sha256=sha(REPO/'workbench/function_fragment.tide'),trials=rows))
main()
